`timescale 1ns / 1ps

//------------------------------------------------------------------------------
// bcnn_core.v
// Binarized CNN inference engine for zebra crossing detection.
//
// The network is described by bcnn_config.vh, generated by python/bcnn_model.py
// (write_mem_files) next to the ROM files, so model and hardware cannot drift:
//   Input : IMG_W x IMG_H grayscale, 8-bit (pixel - 128 used as a signed value)
//   L0    : conv 3x3, 1 -> C0, binary weights on 8-bit pixels, zero pad,
//           threshold -> 1 bit, maxpool 2x2 (= OR)
//   L1..  : conv 3x3, XNOR + popcount over all input channels, pad = -1,
//           threshold, maxpool 2x2
//   last  : fully connected -> 1, done as a "valid" conv over the last map,
//           score = popcount, detect = (score >= threshold)
// v1 (main branch): 40x30, 16-32-32, 32-bit words.
// v2: 80x60, 32-64-64-64, 64-bit words.
//
// Every neuron is "accumulate over taps, then compare with a per-neuron
// threshold" (BatchNorm folded into the threshold in Python). Negative
// BatchNorm gains are folded into the weights, so the compare is always >=.
//
// One kernel tap is processed per clock: for binary layers that is an XNOR +
// popcount over all input channels at once (one WORD-bit word), for L0 one
// signed add/subtract of a pixel.
//
// Pipeline:
//   S0  loop counters -> RAM / ROM addresses
//   S1  RAM data valid -> partial sum (popcount or +/- pixel), registered
//   S2  accumulate, compare with threshold, OR into pooled word, write back
//
// Feature-map RAM: one WORD-bit word per pixel, bit c = channel c (1 = +1,
// 0 = -1). The hidden layers' outputs are packed one after another from
// address 0 (bases in bcnn_config.vh), so all of them remain readable by the
// testbench after inference.
//
// Weight ROM: one WORD-bit word per (layer, output channel, tap), bit c = input
// channel c. Threshold ROM: one signed 16-bit word per output channel.
//
// Synchronous reset throughout (the BRAM address/enable registers must not have
// an asynchronous reset); zebra_top synchronises the reset input.
//------------------------------------------------------------------------------

(* use_dsp = "no" *)
module bcnn_core #(
    parameter WEIGHT_FILE = "bcnn_weights.mem",
    parameter THRESH_FILE = "bcnn_thresh.mem"
)(
    clk, rst_n, img_we, img_waddr, img_wdata, start, busy, done, detect, score, threshold
);

    `include "bcnn_config.vh"

    input  wire                 clk;
    input  wire                 rst_n;       // synchronous, active low

    // Image load port: IMG_W x IMG_H grayscale, address = y*IMG_W + x.
    // Only write while busy is low.
    input  wire                 img_we;
    input  wire [IMG_AW-1:0]    img_waddr;
    input  wire [7:0]           img_wdata;

    input  wire                 start;
    output reg                  busy;
    output reg                  done;        // 1-cycle pulse when result is valid
    output reg                  detect;      // 1 = zebra crossing
    output reg  [15:0]          score;       // output neuron popcount
    output reg  signed [15:0]   threshold;   // detect = (score >= threshold)

    localparam LAST = N_LAYERS - 1;

    //--------------------------------------------------------------------------
    // Memories
    //--------------------------------------------------------------------------
    reg [7:0]      img_mem  [0:NPIX-1];
    reg [WORD-1:0] fmap_mem [0:FMAP_DEPTH-1];
    reg [WORD-1:0] w_rom    [0:W_DEPTH-1];
    reg [15:0]     t_rom    [0:T_DEPTH-1];

    initial begin
        $readmemh(WEIGHT_FILE, w_rom);
        $readmemh(THRESH_FILE, t_rom);
    end

    //--------------------------------------------------------------------------
    // Layer table (from bcnn_config.vh)
    //--------------------------------------------------------------------------
    reg  [LAYER_BITS-1:0] layer;

    reg  [7:0]  in_w, in_h;       // input map size
    reg  [7:0]  cout;             // output channels
    reg  [3:0]  k_w, k_h;         // kernel size
    reg         pad;              // 1 = pad by one pixel, 0 = valid
    reg         pool;             // 1 = 2x2 maxpool after threshold
    reg         byte_in;          // 1 = input is the 8-bit image (L0)
    reg  [7:0]  pw, ph;           // number of (pooled) output positions
    reg  [FMAP_AW-1:0] in_base, out_base;
    reg  [W_AW-1:0]    w_base;
    reg  [T_AW-1:0]    t_base;
    reg  [WORD-1:0]    cin_mask;

    always @(*) begin
        case (layer)
`define BCNN_LAYER_TABLE
`include "bcnn_config.vh"
`undef BCNN_LAYER_TABLE
        endcase
    end

    //--------------------------------------------------------------------------
    // S0: loop counters and addresses
    // Loop order (outer -> inner): py, px, sub (2x2 pool position), co, ky, kx
    //--------------------------------------------------------------------------
    localparam IDLE = 2'd0, RUN = 2'd1, DRAIN = 2'd2, FINISH = 2'd3;
    reg [1:0] state;
    reg [1:0] drain_cnt;

    reg [3:0] kx, ky;
    reg [7:0] co;
    reg [1:0] sub;
    reg [7:0] px, py;

    wire last_kx  = (kx == k_w - 1);
    wire last_ky  = (ky == k_h - 1);
    wire last_co  = (co == cout - 1);
    wire last_sub = pool ? (sub == 2'd3) : 1'b1;
    wire last_px  = (px == pw - 1);
    wire last_py  = (py == ph - 1);

    // Conv output position.
    wire [8:0] oy = pool ? {py, 1'b0} + sub[1] : {1'b0, py};
    wire [8:0] ox = pool ? {px, 1'b0} + sub[0] : {1'b0, px};

    // Input position for this tap (may be -1 or in_w/in_h at the border).
    wire signed [10:0] iy = $signed({2'b0, oy}) + $signed({7'b0, ky}) - $signed({10'b0, pad});
    wire signed [10:0] ix = $signed({2'b0, ox}) + $signed({7'b0, kx}) - $signed({10'b0, pad});
    wire in_bounds = (iy >= 0) && (iy < $signed({3'b0, in_h})) &&
                     (ix >= 0) && (ix < $signed({3'b0, in_w}));

    wire [15:0]        pix_addr   = iy[7:0] * in_w + ix[7:0];
    wire [FMAP_AW-1:0] fmap_raddr = in_base + pix_addr[FMAP_AW-1:0];
    wire [W_AW-1:0]    w_addr     = w_base + co * (k_w * k_h) + ky * k_w + kx;
    wire [T_AW-1:0]    t_addr     = t_base + co;
    wire [FMAP_AW-1:0] out_addr   = out_base + py * pw + px;

    wire s0_valid = (state == RUN);

    //--------------------------------------------------------------------------
    // Memory ports (synchronous read, 1 cycle: address in S0, data in S1)
    //--------------------------------------------------------------------------
    reg [7:0]      img_rdata;
    reg [WORD-1:0] fmap_rdata;
    reg [WORD-1:0] w_rdata;
    reg [15:0]     t_rdata;

    reg               fmap_we;
    reg [FMAP_AW-1:0] fmap_waddr;
    reg [WORD-1:0]    fmap_wdata;

    always @(posedge clk) begin
        if (img_we)
            img_mem[img_waddr] <= img_wdata;
        img_rdata <= img_mem[pix_addr[IMG_AW-1:0]];
    end

    always @(posedge clk) begin
        if (fmap_we)
            fmap_mem[fmap_waddr] <= fmap_wdata;
        fmap_rdata <= fmap_mem[fmap_raddr];
    end

    always @(posedge clk) begin
        w_rdata <= w_rom[w_addr];
        t_rdata <= t_rom[t_addr];
    end

    //--------------------------------------------------------------------------
    // S1: partial sum for one tap
    //--------------------------------------------------------------------------
    reg        s1_valid, s1_inb, s1_first_tap, s1_last_tap;
    reg        s1_first_sub, s1_last_sub, s1_last_co;
    reg [7:0]  s1_co;
    reg [FMAP_AW-1:0] s1_out_addr;

    function [7:0] popcount;
        input [WORD-1:0] v;
        integer b;
        begin
            popcount = 0;
            for (b = 0; b < WORD; b = b + 1)
                popcount = popcount + v[b];
        end
    endfunction

    wire signed [15:0] pix_s   = s1_inb ? $signed({8'b0, img_rdata}) - 16'sd128 : 16'sd0;
    wire    [WORD-1:0] in_word = s1_inb ? fmap_rdata : {WORD{1'b0}};   // pad = all -1
    wire    [WORD-1:0] match   = ~(in_word ^ w_rdata) & cin_mask;

    wire signed [15:0] partial = byte_in ? (w_rdata[0] ? pix_s : -pix_s)
                                         : $signed({8'b0, popcount(match)});

    //--------------------------------------------------------------------------
    // S2: accumulate, threshold, pool, write back
    //--------------------------------------------------------------------------
    reg        s2_valid, s2_first_tap, s2_last_tap;
    reg        s2_first_sub, s2_last_sub, s2_last_co;
    reg [7:0]  s2_co;
    reg [FMAP_AW-1:0] s2_out_addr;
    reg signed [15:0] s2_partial;
    reg signed [15:0] s2_thr;

    reg signed [15:0] acc;
    reg    [WORD-1:0] pool_bits;

    wire signed [15:0] acc_next = s2_first_tap ? s2_partial : acc + s2_partial;
    wire               fire     = (acc_next >= s2_thr);

    reg [WORD-1:0] pool_next;
    always @(*) begin
        pool_next = pool_bits;
        pool_next[s2_co] = (s2_first_sub ? 1'b0 : pool_bits[s2_co]) | fire;
    end

    //--------------------------------------------------------------------------
    // Control and pipeline registers
    //--------------------------------------------------------------------------
    always @(posedge clk) begin
        if (!rst_n) begin
            state <= IDLE;
            drain_cnt <= 0;
            layer <= 0;
            kx <= 0; ky <= 0; co <= 0; sub <= 0; px <= 0; py <= 0;
            busy <= 0;
            done <= 0;
            detect <= 0;
            score <= 0;
            threshold <= 0;
            s1_valid <= 0; s1_inb <= 0; s1_first_tap <= 0; s1_last_tap <= 0;
            s1_first_sub <= 0; s1_last_sub <= 0; s1_last_co <= 0;
            s1_co <= 0; s1_out_addr <= 0;
            s2_valid <= 0; s2_first_tap <= 0; s2_last_tap <= 0;
            s2_first_sub <= 0; s2_last_sub <= 0; s2_last_co <= 0;
            s2_co <= 0; s2_out_addr <= 0; s2_partial <= 0; s2_thr <= 0;
            acc <= 0;
            pool_bits <= 0;
            fmap_we <= 0; fmap_waddr <= 0; fmap_wdata <= 0;
        end else begin
            done    <= 0;
            fmap_we <= 0;

            //------------------------------------------------------------------
            // S0 -> S1
            s1_valid     <= s0_valid;
            s1_inb       <= in_bounds;
            s1_first_tap <= (kx == 0) && (ky == 0);
            s1_last_tap  <= last_kx && last_ky;
            s1_first_sub <= (sub == 0);
            s1_last_sub  <= last_sub;
            s1_last_co   <= last_co;
            s1_co        <= co;
            s1_out_addr  <= out_addr;

            // S1 -> S2
            s2_valid     <= s1_valid;
            s2_first_tap <= s1_first_tap;
            s2_last_tap  <= s1_last_tap;
            s2_first_sub <= s1_first_sub;
            s2_last_sub  <= s1_last_sub;
            s2_last_co   <= s1_last_co;
            s2_co        <= s1_co;
            s2_out_addr  <= s1_out_addr;
            s2_partial   <= partial;
            s2_thr       <= $signed(t_rdata);

            // S2
            if (s2_valid) begin
                acc <= acc_next;
                if (s2_last_tap) begin
                    pool_bits <= pool_next;
                    if (layer == LAST) begin
                        score     <= acc_next;
                        detect    <= fire;
                        threshold <= s2_thr;
                    end else if (s2_last_co && s2_last_sub) begin
                        fmap_we    <= 1;
                        fmap_waddr <= s2_out_addr;
                        fmap_wdata <= pool_next;
                    end
                end
            end

            //------------------------------------------------------------------
            // Loop counters
            case (state)
                IDLE: begin
                    if (start) begin
                        busy  <= 1;
                        layer <= 0;
                        kx <= 0; ky <= 0; co <= 0; sub <= 0; px <= 0; py <= 0;
                        pool_bits <= 0;
                        state <= RUN;
                    end
                end

                RUN: begin
                    if (!last_kx) kx <= kx + 1;
                    else begin
                        kx <= 0;
                        if (!last_ky) ky <= ky + 1;
                        else begin
                            ky <= 0;
                            if (!last_co) co <= co + 1;
                            else begin
                                co <= 0;
                                if (!last_sub) sub <= sub + 1;
                                else begin
                                    sub <= 0;
                                    if (!last_px) px <= px + 1;
                                    else begin
                                        px <= 0;
                                        if (!last_py) py <= py + 1;
                                        else begin
                                            py <= 0;
                                            drain_cnt <= 0;
                                            state <= DRAIN;
                                        end
                                    end
                                end
                            end
                        end
                    end
                end

                // Let the last taps leave S1/S2 (and the last word reach the
                // RAM) before the next layer starts reading it.
                DRAIN: begin
                    drain_cnt <= drain_cnt + 1;
                    if (drain_cnt == 2'd3) begin
                        if (layer == LAST) begin
                            state <= FINISH;
                        end else begin
                            layer <= layer + 1;
                            pool_bits <= 0;
                            state <= RUN;
                        end
                    end
                end

                FINISH: begin
                    busy  <= 0;
                    done  <= 1;
                    state <= IDLE;
                end
            endcase
        end
    end

endmodule
